          "import math",
          "import pandas as pd",
          "from pyodide.http import open_url",
          "",
          "URL = \"/misi/misi-gabung-uji-ab-jujur/assignments.csv\"",
          "df = pd.read_csv(open_url(URL))",
          "",
          "def phi(z):",
          "    return 0.5 * (1.0 + math.erf(z / math.sqrt(2.0)))",
          "",
          "def uji_z(cA, nA, cB, nB):",
          "    # uji dua sisi selisih dua proporsi, varians pooled -> (z, p)",
          "    pA = cA / nA",
          "    pB = cB / nB",
          "    p_bar = (cA + cB) / (nA + nB)",
          "    se = math.sqrt(p_bar * (1 - p_bar) * (1 / nA + 1 / nB))",
          "    z = (pB - pA) / se",
          "    p = 2 * (1 - phi(abs(z)))",
          "    return z, p",
          "",
          "def ringkas(grup, tgl_maks, segmen=None):",
          "    # -> (jumlah konversi, n) untuk grup & tanggal <= tgl_maks",
          "    sub = df[(df[\"grup\"] == grup) & (df[\"tanggal\"] <= tgl_maks)]",
          "    if segmen is not None:",
          "        sub = sub[sub[\"segmen\"] == segmen]",
          "    return int(sub[\"konversi\"].sum()), len(sub)",
          "",
          "def power_efek(pA, pB, n_per_grup):",
          "    # power uji dua sisi mendeteksi selisih pB-pA",
          "    z_alfa = 1.959963984540054",
          "    p_bar = (pA + pB) / 2",
          "    se = math.sqrt(p_bar * (1 - p_bar) * 2 / n_per_grup)",
          "    delta = abs(pB - pA)",
          "    return phi(delta / se - z_alfa) + phi(-delta / se - z_alfa)",
          "",
          "# ── t1: intipan kumulatif hari 2..6 ──",
          "n_baris = len(df)",
          "p_intip = {}",
          "for d in [2, 3, 4, 5, 6]:",
          "    tgl = \"2026-06-%02d\" % d",
          "    cA, nA = ringkas(\"A\", tgl)",
          "    cB, nB = ringkas(\"B\", tgl)",
          "    z, p = uji_z(cA, nA, cB, nB)",
          "    p_intip[d] = p",
          "p_hari5 = p_intip[5]",
          "p_hari6 = p_intip[6]",
          "",
          "# ── t2: power aktual vs klaim (titik berhenti: 1200/grup) ──",
          "cA, nA = ringkas(\"A\", \"2026-06-06\")",
          "cB, nB = ringkas(\"B\", \"2026-06-06\")",
          "pA_klaim, pB_klaim = cA / nA, cB / nB",
          "power_aktual = power_efek(pA_klaim, pB_klaim, nA)",
          "z_beta = 0.8416212335729143  # power 80%",
          "p_bar_klaim = (pA_klaim + pB_klaim) / 2",
          "n_dibutuhkan = ((1.959963984540054 + z_beta) * math.sqrt(2 * p_bar_klaim * (1 - p_bar_klaim)) / abs(pB_klaim - pA_klaim)) ** 2",
          "",
          "# ── t3: 8 segmen + Bonferroni ──",
          "p_segmen = {}",
          "for s in [\"S1\",\"S2\",\"S3\",\"S4\",\"S5\",\"S6\",\"S7\",\"S8\"]:",
          "    cA, nA = ringkas(\"A\", \"2026-06-10\", segmen=s)",
          "    cB, nB = ringkas(\"B\", \"2026-06-10\", segmen=s)",
          "    z, p = uji_z(cA, nA, cB, nB)",
          "    p_segmen[s] = p",
          "alpha_bonf = 0.05 / 8",
          "p_s7_mentah = p_segmen[\"S7\"]",
          "n_sig_mentah = sum(1 for p in p_segmen.values() if p < 0.05)",
          "n_sig_bonferroni = sum(1 for p in p_segmen.values() if p < alpha_bonf)",
          "",
          "# ── t4: uji ulang full 10 hari ──",
          "cA, nA = ringkas(\"A\", \"2026-06-10\")",
          "cB, nB = ringkas(\"B\", \"2026-06-10\")",
          "z_final, p_final = uji_z(cA, nA, cB, nB)",
          "",
          "print(\"baris:\", n_baris)",
          "print(\"intipan:\", {d: round(p_intip[d], 4) for d in p_intip})",
          "print(\"power aktual:\", round(power_aktual, 4), \"| n dibutuhkan/grup:\", round(n_dibutuhkan))",
          "print(\"S7 mentah:\", round(p_s7_mentah, 4), \"| sig mentah:\", n_sig_mentah, \"| sig Bonferroni:\", n_sig_bonferroni)",
